137→        assert_eq!(InstallMethod::Cargo.name(), "cargo");
138→        assert_eq!(InstallMethod::Homebrew.name(), "homebrew");
139→        assert_eq!(
140→            InstallMethod::Manual {
141→                path: PathBuf::from("/usr/bin/bivvy")
142→            }
143→            .name(),
144→            "manual"
145→        );
146→        assert_eq!(InstallMethod::Unknown.name(), "unknown");
147→    }
