539→
540→        server.mock(|when, then| {
541→            when.method(GET).path("/concurrent.yml");
542→            then.status(200).body("concurrent: true\ndata: value\n");
543→        });
544→
545→        let temp = TempDir::new().unwrap();
546→        let cache_dir = temp.path().join("cache");
547→        let url = server.url("/concurrent.yml");
548→
549→        // Create multiple threads that all fetch the same URL
550→        let handles: Vec<_> = (0..4)
551→            .map(|_| {
552→                let url = url.clone();
553→                let cache_dir = cache_dir.clone();
554→                std::thread::spawn(move || {
555→                    let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
556→                    fetcher.fetch(&url).unwrap()
557→                })
558→            })
559→            .collect();
560→
561→        let results: Vec<String> = handles.into_iter().map(|h| h.join().unwrap()).collect();
562→
563→        // All threads should get the correct content
564→        for result in &results {
565→            assert_eq!(result, "concurrent: true\ndata: value\n");
566→        }
567→    }
