571→        let server = MockServer::start();
572→
573→        let mock = server.mock(|when, then| {
574→            when.method(GET).path("/corrupt.yml");
575→            then.status(200).body("valid: true");
576→        });
577→
578→        let temp = TempDir::new().unwrap();
579→        let cache_dir = temp.path().join("cache");
580→        let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
581→        let url = server.url("/corrupt.yml");
582→
583→        // Warm the cache normally
584→        fetcher.fetch(&url).unwrap();
585→        mock.assert_calls(1);
586→
587→        // Corrupt the cache file by writing garbage
588→        let cache_path = fetcher.cache_path(&url);
589→        std::fs::write(&cache_path, "garbage\x00\x01\x02not yaml").unwrap();
590→
591→        // The fetcher's simple cache returns whatever is in the file,
592→        // so it will return the corrupted content. This is by design:
593→        // RemoteFetcher's cache is a simple file-based cache without
594→        // integrity checks. The caller (ExtendsResolver) handles
595→        // YAML parse errors.
596→        let content = fetcher.fetch(&url).unwrap();
597→        assert_eq!(content, "garbage\x00\x01\x02not yaml");
598→        // Still only 1 server hit (cache was returned, even if corrupted)
599→        mock.assert_calls(1);
600→    }
601→}
