  1→//! Project identification and hashing.
  2→//!
  3→//! This module provides unique project identification using SHA256 hashing
  4→//! of the project path and git remote URL.
  5→
  6→use sha2::{Digest, Sha256};
  7→use std::path::{Path, PathBuf};
  8→
  9→use crate::error::Result;
 10→
 11→/// Unique identifier for a project.
 12→///
 13→/// Projects are identified by a combination of their absolute path and
 14→/// git remote URL (if available). This produces a stable hash that can
 15→/// be used as a directory name for storing state.
 16→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
 17→pub struct ProjectId {
 18→    /// SHA256 hash of project identification data.
 19→    hash: String,
 20→    /// Absolute path to the project root.
 21→    path: PathBuf,
 22→    /// Git remote URL if available.
 23→    git_remote: Option<String>,
 24→}
 25→
 26→impl ProjectId {
 27→    /// Create a ProjectId from a project path.
 28→    ///
 29→    /// The path will be canonicalized to an absolute path. Git remote
 30→    /// detection is attempted using system git.
 31→    ///
 32→    /// # Errors
 33→    ///
 34→    /// Returns an error if the path cannot be canonicalized (e.g., doesn't exist).
 35→    pub fn from_path(path: &Path) -> Result<Self> {
 36→        let abs_path = path.canonicalize().map_err(crate::error::BivvyError::Io)?;
 37→
 38→        let git_remote = Self::detect_git_remote(&abs_path);
 39→        let hash = Self::compute_hash(&abs_path, git_remote.as_deref());
 40→
 41→        Ok(Self {
 42→            hash,
 43→            path: abs_path,
 44→            git_remote,
 45→        })
 46→    }
 47→
 48→    /// Get the hash as a string.
 49→    ///
 50→    /// This is a 16-character hex string (8 bytes of SHA256).
 51→    pub fn hash(&self) -> &str {
 52→        &self.hash
 53→    }
 54→
 55→    /// Get the project path.
 56→    pub fn path(&self) -> &Path {
 57→        &self.path
 58→    }
 59→
 60→    /// Get the git remote URL if available.
 61→    pub fn git_remote(&self) -> Option<&str> {
 62→        self.git_remote.as_deref()
 63→    }
 64→
 65→    /// Get the project name (directory name).
 66→    pub fn name(&self) -> &str {
 67→        self.path
 68→            .file_name()
 69→            .and_then(|n| n.to_str())
 70→            .unwrap_or("unknown")
 71→    }
 72→
 73→    fn detect_git_remote(path: &Path) -> Option<String> {
 74→        let output = std::process::Command::new("git")
 75→            .args(["remote", "get-url", "origin"])
 76→            .current_dir(path)
 77→            .stdout(std::process::Stdio::piped())
 78→            .stderr(std::process::Stdio::null())
 79→            .output()
 80→            .ok()?;
 81→
 82→        if !output.status.success() {
 83→            return None;
 84→        }
 85→
 86→        let url = String::from_utf8(output.stdout).ok()?;
 87→        let url = url.trim();
 88→        if url.is_empty() {
 89→            None
 90→        } else {
 91→            Some(url.to_string())
 92→        }
 93→    }
 94→
 95→    fn compute_hash(path: &Path, git_remote: Option<&str>) -> String {
 96→        let mut hasher = Sha256::new();
 97→
 98→        hasher.update(path.to_string_lossy().as_bytes());
 99→
100→        if let Some(remote) = git_remote {
101→            hasher.update(remote.as_bytes());
102→        }
103→
104→        let result = hasher.finalize();
105→        hex::encode(&result[..8]) // Use first 8 bytes (16 hex chars)
106→    }
107→}
